fn render_workspace_header(role: ConfigRole, agent_repo: Option<&str>) -> String {
    match role {
        ConfigRole::DualWork => {
            // The agent-repo's remote name is the work side's to
            // record: clone and sync read it from here, since at the
            // moment they need it there is no agent-repo to ask. It
            // gets a table of its own because `[repos]` registers
            // local paths and this is a remote name. A `None` name
            // omits the table, which is the shape every workspace
            // created before the key has, and reads as the work name
            // plus `.claude`.
            let remote_table = match agent_repo {
                Some(name) => format!("\n[remote]\nagent = \"{name}\"\n"),
                None => String::new(),
            };
            format!(
                r#"# vc-config: Vibe Coding workspace configuration
#
# [repos] is the workspace's repo registry: work and bot are paths
# relative to this file's directory (absolute allowed, discouraged).
# The entry that resolves to this config's own directory names the
# side: work = "." makes this the work repo.
#
# [remote] holds remote names rather than paths. agent is the
# agent-repo's name on its remote, the last URL segment only, since
# the owner and the host come from the work repo's own remote.

[repos]
work = "."
agent = ".claude"
{remote_table}"#
            )
        }
        ConfigRole::DualBot => r#"# vc-config: Vibe Coding workspace configuration
#
# [repos] is the workspace's repo registry: work and bot are paths
# relative to this file's directory (absolute allowed, discouraged).
# The entry that resolves to this config's own directory names the
# side: agent = "." makes this the agent repo.

[repos]
work = ".."
agent = "."
"#
        .to_string(),
    let base = ws_tempdir("agent-repo-key");
    let root = base.join("ws");
    std::fs::create_dir_all(&root).unwrap();

    std::fs::write(root.join(VC_CONFIG_FILE), WORK_DUAL).unwrap();
    assert_eq!(configured_agent_repo(&root).unwrap(), None);

    let with_key = format!("{WORK_DUAL}\n[remote]\nagent = \"ws.agent-session\"\n");
    std::fs::write(root.join(VC_CONFIG_FILE), with_key).unwrap();
    assert_eq!(
        configured_agent_repo(&root).unwrap().as_deref(),
        Some("ws.agent-session")
    );

    std::fs::remove_dir_all(&base).ok();
}
    let work = render_vc_config(ConfigRole::DualWork, Some("proj.claude"));
    assert!(work.contains("work = \".\""));
    assert!(work.contains("agent = \".claude\""));
    // The work side records the agent-repo's remote name, since it is
    // what clone and sync read before an agent-repo exists to ask.
    // An active line, not the header comment that also names the
    // table.
    assert!(work.lines().any(|l| l.trim_start() == "[remote]"));
    assert!(work.contains("agent = \"proj.claude\""));
    let bot = render_vc_config(ConfigRole::DualBot, None);
    assert!(bot.contains("work = \"..\""));
    assert!(bot.contains("agent = \".\""));
    assert!(!bot.lines().any(|l| l.trim_start() == "[remote]"));
}

/// No name renders no `agent-repo` line, which is the shape of every
/// workspace created before the key and reads as the work repo's name
/// plus `.claude`.
#[test]
fn config_content_dual_without_an_agent_repo_name() {
    let work = render_vc_config(ConfigRole::DualWork, None);
    assert!(work.contains("agent = \".claude\""));
    assert!(
        !work.lines().any(|l| l.trim_start() == "[remote]"),
        "no active [remote] table"
    );
}

#[test]
fn config_optional_keys_are_commented_only() {
    let work = render_vc_config(ConfigRole::DualWork, None);
    // The doc-block header/used-by/default lines precede the
    // commented assignment.
    assert!(work.contains("used by: agent-session --col-width"));
    assert!(work.contains("used by: agent-session --result-lines"));
    assert!(work.contains("# col-width = 68"));
    assert!(work.contains("# result-lines = 10"));
    assert!(
        !work
            .lines()
            .any(|l| l.trim_start().starts_with("col-width"))
    );
    assert!(
        !work
            .lines()
            .any(|l| l.trim_start().starts_with("result-lines"))
    );
}

#[test]
fn config_generated_toml_parses_to_active_keys_only() {
    let dir = std::env::temp_dir().join(format!(
        "vcx1-init-config-test-{}-{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::SystemTime::UNIX_EPOCH)
            .map(|d| d.as_nanos())
            .unwrap_or(0) // OK: test-only uniqueness suffix, and 0 fallback is harmless
    ));
    std::fs::create_dir_all(&dir).expect("create temp dir");
    let path = dir.join(crate::config_md::VC_CONFIG_MD);
    std::fs::write(
        &path,
        render_vc_config(ConfigRole::DualWork, Some("proj.claude")),
    )
    .expect("write config");

    let map = crate::config_md::load_file(&path).expect("parse generated config");
    assert_eq!(map.get("repos.work").map(String::as_str), Some("."));
    assert_eq!(map.get("repos.agent").map(String::as_str), Some(".claude"));
    assert_eq!(
        map.get("remote.agent").map(String::as_str),
        Some("proj.claude")
    );
    assert!(!map.contains_key("agent-session.col-width"));
    assert!(!map.contains_key("push.state-file"));

    let _ = std::fs::remove_dir_all(&dir);
}

