1	//! Init's steps, numbered in the order a plan runs them.
2	//!
3	//! One list serves the dry run, which prints it whole, and the real
4	//! run, which prints each step as it starts, so the two cannot
5	//! number or name a step differently. A step a plan does not run is
6	//! left out rather than printed as skipped, so the numbers run
7	//! 1..=N with no gaps.
8	
9	use std::path::PathBuf;
10	
11	use log::info;
12	
13	use super::{AgentPlan, InitParams, InitPlan, Provisioner};
14	use crate::options_flags::config::ConfigKind;
15	
16	/// One step of an init run.
17	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
18	pub(crate) enum Step {
19	    PrepareWork,
20	    ConfigWork,
21	    CommitWork,
22	    PrepareAgent,
23	    ConfigAgent,
24	    CommitAgent,
25	    CrossLink,
26	    PublishAgent,
27	    PublishWork,
28	    Symlink,
29	}
30	
31	/// A plan's steps, each with its title.
32	pub(crate) struct Steps {
33	    list: Vec<(Step, String)>,
34	}
35	
36	impl Steps {
37	    /// The steps `plan` runs, titled with what each will do to what.
38	    pub(crate) fn new(
39	        plan: &InitPlan,
40	        params: &InitParams,
41	        templates: Option<&(PathBuf, Option<PathBuf>)>,
42	        visibility: &str,
43	        create_symlink: bool,
44	    ) -> Self {
45	        let work_template = templates.map(|(w, _)| w);
46	        let agent_template = templates.and_then(|(_, a)| a.as_ref());
47	        let mut list = Vec::new();
48	
49	        let work_dir = plan.project_dir.display();
50	        let prepare_work = if params.adopt {
51	            format!("Init the work repo (jj, colocated) in {work_dir}, adopting its content")
52	        } else {
53	            format!("Create {work_dir} and init the work repo (jj, colocated)")
54	        };
55	        list.push((
56	            Step::PrepareWork,
57	            with_template(prepare_work, work_template),
58	        ));
59	        let config_work = match (&plan.agent, &params.config) {
60	            (Some(_), _) | (None, None) => {
61	                "Write the work repo's .vc-config.md and .gitignore".into()
62	            }
63	            (None, Some(ConfigKind::None)) => {
64	                "Write the work repo's .gitignore (no .vc-config.md, per --config none)".into()
65	            }
66	            (None, Some(ConfigKind::Path(p))) => format!(
67	                "Copy {} as the work repo's config and write its .gitignore",
68	                p.display()
69	            ),
70	        };
71	        list.push((Step::ConfigWork, config_work));
72	        list.push((
73	            Step::CommitWork,
74	            "Commit the work repo's initial commit".into(),
75	        ));
76	
77	        if let Some(agent) = &plan.agent {
78	            let prepare_agent = format!(
79	                "Create {} and init the agent repo (jj, colocated)",
80	                agent.path.display()
81	            );
82	            list.push((
83	                Step::PrepareAgent,
84	                with_template(prepare_agent, agent_template),
85	            ));
86	            list.push((
87	                Step::ConfigAgent,
88	                "Write the agent repo's .vc-config.md and .gitignore".into(),
89	            ));
90	            list.push((
91	                Step::CommitAgent,
92	                "Commit the agent repo's initial commit".into(),
93	            ));
94	            list.push((
95	                Step::CrossLink,
96	                "Cross-link the two initial commits with ochid trailers".into(),
97	            ));
98	            list.push((
99	                Step::PublishAgent,
100	                publish_title(plan, "agent", Some(agent), visibility),
101	            ));
102	        }
103	        list.push((
104	            Step::PublishWork,
105	            publish_title(plan, "work", None, visibility),
106	        ));
107	        if plan.agent.is_some() && create_symlink {
108	            list.push((Step::Symlink, "Create the Claude Code symlink".into()));
109	        }
110	        Self { list }
111	    }
112	
113	    /// Print the whole list, for the dry run.
114	    pub(crate) fn print_all(&self) {
115	        for (i, (_, title)) in self.list.iter().enumerate() {
116	            info!("  {}. {title}", i + 1);
117	        }
118	    }
119	
120	    /// Announce `step` as it starts, numbered by its place in the
121	    /// list. A step the list lacks is a bug in the caller, logged
122	    /// unnumbered rather than failing the run it narrates.
123	    pub(crate) fn begin(&self, step: Step) {
124	        match self.list.iter().position(|(s, _)| *s == step) {
125	            Some(i) => info!("Step {}: {}", i + 1, self.list[i].1),
126	            None => info!("Step: {step:?}"),
