145	/// A publish step's title: set `main`, provision the remote the plan
146	/// names, and push. `agent` is the agent side's plan, `None` for the
147	/// work side.
148	fn publish_title(
149	    plan: &InitPlan,
150	    side: &str,
151	    agent: Option<&AgentPlan>,
152	    visibility: &str,
153	) -> String {
154	    let (url, slug, bare) = match agent {
155	        Some(a) => (a.url.as_str(), a.gh_slug.as_deref(), a.bare_path.as_ref()),
156	        None => (
157	            plan.work_url.as_str(),
158	            plan.gh_work_slug.as_deref(),
159	            plan.work_bare_path.as_ref(),
160	        ),
161	    };
162	    let remote = match (&plan.provisioner, slug, bare) {
163	        (Provisioner::GhCreate, Some(slug), _) => format!("create GitHub repo {slug} {visibility}"),
164	        (Provisioner::LocalBareInit, _, Some(bare)) => {
165	            format!("create bare repo {}", bare.display())
166	        }
167	        _ => "use the existing remote".to_string(),
168	    };
169	    format!("Set main on the {side} repo's initial commit, {remote}, and push to {url}")
170	}

