52	        } else {
53	            format!("Create {work_dir} and init the work repo (jj, colocated)")
54	        };
55	        // An adopted repo is prepared already.
56	        if plan.work_start == WorkStart::Fresh {
57	            list.push((
58	                Step::PrepareWork,
